// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetLiveness Liveness of the engine process
	// (GET /healthz)
	GetLiveness(w http.ResponseWriter, r *http.Request)
	// GetReadiness Readiness of the engine and its database
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// ExplainAccess Explain a person's access to a folder
	// (POST /v1/authz/explain)
	ExplainAccess(w http.ResponseWriter, r *http.Request)
	// ListCommands Catalog commands the caller may run
	// (GET /v1/commands)
	ListCommands(w http.ResponseWriter, r *http.Request)
	// PreviewCommand Show the exact arguments a run would use
	// (POST /v1/commands/preview)
	PreviewCommand(w http.ResponseWriter, r *http.Request)
	// PlanDelete Measure a deletion before doing it
	// (POST /v1/fs/delete/plan)
	PlanDelete(w http.ResponseWriter, r *http.Request)
	// StatEntry Describe one file or folder
	// (GET /v1/fs/entry)
	StatEntry(w http.ResponseWriter, r *http.Request, params StatEntryParams)
	// ListDirectory List a directory the caller may see
	// (GET /v1/fs/list)
	ListDirectory(w http.ResponseWriter, r *http.Request, params ListDirectoryParams)
	// GetMediaInfo How a video can be played in the browser
	// (GET /v1/fs/media)
	GetMediaInfo(w http.ResponseWriter, r *http.Request, params GetMediaInfoParams)
	// CreateFolder Create a folder
	// (POST /v1/fs/mkdir)
	CreateFolder(w http.ResponseWriter, r *http.Request)
	// GetEntryProperties Details of one file or folder for the Properties dialog
	// (GET /v1/fs/properties)
	GetEntryProperties(w http.ResponseWriter, r *http.Request, params GetEntryPropertiesParams)
	// RenameEntry Rename an entry in place
	// (POST /v1/fs/rename)
	RenameEntry(w http.ResponseWriter, r *http.Request)
	// SearchFiles Find files and folders by name under a folder
	// (GET /v1/fs/search)
	SearchFiles(w http.ResponseWriter, r *http.Request, params SearchFilesParams)
	// PlanTransfer Check a copy or move before running it
	// (POST /v1/fs/transfer/plan)
	PlanTransfer(w http.ResponseWriter, r *http.Request)
	// MoveToTrash Move items to the trash
	// (POST /v1/fs/trash)
	MoveToTrash(w http.ResponseWriter, r *http.Request)
	// ListJobs Recent jobs of the caller
	// (GET /v1/jobs)
	ListJobs(w http.ResponseWriter, r *http.Request, params ListJobsParams)
	// StartChecksum Compute a file checksum
	// (POST /v1/jobs/checksum)
	StartChecksum(w http.ResponseWriter, r *http.Request)
	// StartCommand Run a catalog command
	// (POST /v1/jobs/command)
	StartCommand(w http.ResponseWriter, r *http.Request)
	// StartCompress Compress items into an archive
	// (POST /v1/jobs/compress)
	StartCompress(w http.ResponseWriter, r *http.Request)
	// StartPermanentDelete Delete items permanently
	// (POST /v1/jobs/delete)
	StartPermanentDelete(w http.ResponseWriter, r *http.Request)
	// StartEmptyTrash Remove trash items for good
	// (POST /v1/jobs/empty-trash)
	StartEmptyTrash(w http.ResponseWriter, r *http.Request)
	// StartExtract Extract an archive next to it
	// (POST /v1/jobs/extract)
	StartExtract(w http.ResponseWriter, r *http.Request)
	// StartFolderSize Measure a folder in the background
	// (POST /v1/jobs/folder-size)
	StartFolderSize(w http.ResponseWriter, r *http.Request)
	// StartTransfer Copy or move entries in the background
	// (POST /v1/jobs/transfer)
	StartTransfer(w http.ResponseWriter, r *http.Request)
	// GetJob One job
	// (GET /v1/jobs/{jobId})
	GetJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID)
	// CancelJob Cancel a queued or running job
	// (POST /v1/jobs/{jobId}/cancel)
	CancelJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID)
	// GetJobLogs Output lines of a job
	// (GET /v1/jobs/{jobId}/logs)
	GetJobLogs(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID, params GetJobLogsParams)
	// ListPlugins Installed plugins
	// (GET /v1/plugins)
	ListPlugins(w http.ResponseWriter, r *http.Request)
	// InstallPlugin Install or update a plugin from its release files
	// (POST /v1/plugins)
	InstallPlugin(w http.ResponseWriter, r *http.Request)
	// InspectPlugin Check a release manifest before downloading its binary
	// (POST /v1/plugins/inspect)
	InspectPlugin(w http.ResponseWriter, r *http.Request)
	// UninstallPlugin Uninstall a plugin
	// (DELETE /v1/plugins/{pluginId})
	UninstallPlugin(w http.ResponseWriter, r *http.Request, pluginId string)
	// UpdatePlugin Enable, disable, pin or unpin a plugin
	// (PATCH /v1/plugins/{pluginId})
	UpdatePlugin(w http.ResponseWriter, r *http.Request, pluginId string)
	// ListTrash Items in the trash
	// (GET /v1/trash)
	ListTrash(w http.ResponseWriter, r *http.Request)
	// RestoreFromTrash Put items back where they were
	// (POST /v1/trash/restore)
	RestoreFromTrash(w http.ResponseWriter, r *http.Request)
}

