// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetLiveness Liveness of the engine process
	// (GET /healthz)
	GetLiveness(ctx context.Context, request GetLivenessRequestObject) (GetLivenessResponseObject, error)
	// GetReadiness Readiness of the engine and its database
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// ExplainAccess Explain a person's access to a folder
	// (POST /v1/authz/explain)
	ExplainAccess(ctx context.Context, request ExplainAccessRequestObject) (ExplainAccessResponseObject, error)
	// ListCommands Catalog commands the caller may run
	// (GET /v1/commands)
	ListCommands(ctx context.Context, request ListCommandsRequestObject) (ListCommandsResponseObject, error)
	// PreviewCommand Show the exact arguments a run would use
	// (POST /v1/commands/preview)
	PreviewCommand(ctx context.Context, request PreviewCommandRequestObject) (PreviewCommandResponseObject, error)
	// PlanDelete Measure a deletion before doing it
	// (POST /v1/fs/delete/plan)
	PlanDelete(ctx context.Context, request PlanDeleteRequestObject) (PlanDeleteResponseObject, error)
	// StatEntry Describe one file or folder
	// (GET /v1/fs/entry)
	StatEntry(ctx context.Context, request StatEntryRequestObject) (StatEntryResponseObject, error)
	// ListDirectory List a directory the caller may see
	// (GET /v1/fs/list)
	ListDirectory(ctx context.Context, request ListDirectoryRequestObject) (ListDirectoryResponseObject, error)
	// GetMediaInfo How a video can be played in the browser
	// (GET /v1/fs/media)
	GetMediaInfo(ctx context.Context, request GetMediaInfoRequestObject) (GetMediaInfoResponseObject, error)
	// CreateFolder Create a folder
	// (POST /v1/fs/mkdir)
	CreateFolder(ctx context.Context, request CreateFolderRequestObject) (CreateFolderResponseObject, error)
	// GetEntryProperties Details of one file or folder for the Properties dialog
	// (GET /v1/fs/properties)
	GetEntryProperties(ctx context.Context, request GetEntryPropertiesRequestObject) (GetEntryPropertiesResponseObject, error)
	// RenameEntry Rename an entry in place
	// (POST /v1/fs/rename)
	RenameEntry(ctx context.Context, request RenameEntryRequestObject) (RenameEntryResponseObject, error)
	// SearchFiles Find files and folders by name under a folder
	// (GET /v1/fs/search)
	SearchFiles(ctx context.Context, request SearchFilesRequestObject) (SearchFilesResponseObject, error)
	// PlanTransfer Check a copy or move before running it
	// (POST /v1/fs/transfer/plan)
	PlanTransfer(ctx context.Context, request PlanTransferRequestObject) (PlanTransferResponseObject, error)
	// MoveToTrash Move items to the trash
	// (POST /v1/fs/trash)
	MoveToTrash(ctx context.Context, request MoveToTrashRequestObject) (MoveToTrashResponseObject, error)
	// ListJobs Recent jobs of the caller
	// (GET /v1/jobs)
	ListJobs(ctx context.Context, request ListJobsRequestObject) (ListJobsResponseObject, error)
	// StartChecksum Compute a file checksum
	// (POST /v1/jobs/checksum)
	StartChecksum(ctx context.Context, request StartChecksumRequestObject) (StartChecksumResponseObject, error)
	// StartCommand Run a catalog command
	// (POST /v1/jobs/command)
	StartCommand(ctx context.Context, request StartCommandRequestObject) (StartCommandResponseObject, error)
	// StartCompress Compress items into an archive
	// (POST /v1/jobs/compress)
	StartCompress(ctx context.Context, request StartCompressRequestObject) (StartCompressResponseObject, error)
	// StartPermanentDelete Delete items permanently
	// (POST /v1/jobs/delete)
	StartPermanentDelete(ctx context.Context, request StartPermanentDeleteRequestObject) (StartPermanentDeleteResponseObject, error)
	// StartEmptyTrash Remove trash items for good
	// (POST /v1/jobs/empty-trash)
	StartEmptyTrash(ctx context.Context, request StartEmptyTrashRequestObject) (StartEmptyTrashResponseObject, error)
	// StartExtract Extract an archive next to it
	// (POST /v1/jobs/extract)
	StartExtract(ctx context.Context, request StartExtractRequestObject) (StartExtractResponseObject, error)
	// StartFolderSize Measure a folder in the background
	// (POST /v1/jobs/folder-size)
	StartFolderSize(ctx context.Context, request StartFolderSizeRequestObject) (StartFolderSizeResponseObject, error)
	// StartTransfer Copy or move entries in the background
	// (POST /v1/jobs/transfer)
	StartTransfer(ctx context.Context, request StartTransferRequestObject) (StartTransferResponseObject, error)
	// GetJob One job
	// (GET /v1/jobs/{jobId})
	GetJob(ctx context.Context, request GetJobRequestObject) (GetJobResponseObject, error)
	// CancelJob Cancel a queued or running job
	// (POST /v1/jobs/{jobId}/cancel)
	CancelJob(ctx context.Context, request CancelJobRequestObject) (CancelJobResponseObject, error)
	// GetJobLogs Output lines of a job
	// (GET /v1/jobs/{jobId}/logs)
	GetJobLogs(ctx context.Context, request GetJobLogsRequestObject) (GetJobLogsResponseObject, error)
	// ListPlugins Installed plugins
	// (GET /v1/plugins)
	ListPlugins(ctx context.Context, request ListPluginsRequestObject) (ListPluginsResponseObject, error)
	// InstallPlugin Install or update a plugin from its release files
	// (POST /v1/plugins)
	InstallPlugin(ctx context.Context, request InstallPluginRequestObject) (InstallPluginResponseObject, error)
	// InspectPlugin Check a release manifest before downloading its binary
	// (POST /v1/plugins/inspect)
	InspectPlugin(ctx context.Context, request InspectPluginRequestObject) (InspectPluginResponseObject, error)
	// UninstallPlugin Uninstall a plugin
	// (DELETE /v1/plugins/{pluginId})
	UninstallPlugin(ctx context.Context, request UninstallPluginRequestObject) (UninstallPluginResponseObject, error)
	// UpdatePlugin Enable, disable, pin or unpin a plugin
	// (PATCH /v1/plugins/{pluginId})
	UpdatePlugin(ctx context.Context, request UpdatePluginRequestObject) (UpdatePluginResponseObject, error)
	// ListTrash Items in the trash
	// (GET /v1/trash)
	ListTrash(ctx context.Context, request ListTrashRequestObject) (ListTrashResponseObject, error)
	// RestoreFromTrash Put items back where they were
	// (POST /v1/trash/restore)
	RestoreFromTrash(ctx context.Context, request RestoreFromTrashRequestObject) (RestoreFromTrashResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

